/*! super tiny WebVTT parser */
(function(global){
  function parseTime(s){
    var t = s.trim().split(':'), h=0,m=0,rest;
    if(t.length===3){ h=parseInt(t[0],10); m=parseInt(t[1],10); rest=t[2]; }
    else { m=parseInt(t[0],10); rest=t[1]; }
    var ms = parseFloat(rest.replace(',', '.'));
    var sec = Math.floor(ms); var frac = ms-sec;
    return h*3600 + m*60 + sec + frac;
  }
  function parse(vtt){
    var lines=vtt.replace(/\r/g,'').split('\n');
    var cues=[], i=0;
    while(i<lines.length){
      var line=lines[i].trim();
      if(!line){ i++; continue; }
      if(line.indexOf('-->')!==-1){
        var parts=line.split('-->');
        var start=parseTime(parts[0]);
        var end=parseTime(parts[1]);
        i++;
        var text=[];
        while(i<lines.length && lines[i].trim()!==''){
          text.push(lines[i]); i++;
        }
        cues.push({start:start, end:end, text:text.join('\n')});
      } else {
        i++;
      }
    }
    return cues;
  }
  global.TinyVTT = { parse: parse };
})(this);
